INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'Что такое циркониевая коронка? Преимущества и ограничения',
'<p>Диоксид циркония — безметалловый керамический материал, применяемый в стоматологии для изготовления коронок и мостов. Поскольку он пропускает свет схожим с естественной тканью зуба образом и обладает высокой прочностью на излом, его рассматривают как во фронтальном, так и в боковом отделе. Однако единственно верного материала для каждой полости рта не существует: выбор делается с учётом положения зуба, сохранившихся здоровых тканей, жевательной нагрузки и эстетических ожиданий.</p>
<h2>Что такое циркониевая коронка?</h2>
<p>Это реставрация, изготавливаемая на каркасе из диоксида циркония с облицовкой керамикой при необходимости. Её главное отличие от металлокерамики в том, что в ней нет металлического каркаса; поэтому отсутствует риск серого просвечивания, которое со временем может стать заметным у края десны.</p>
<p>Диоксид циркония бывает разным. Более прозрачные разновидности предпочитают во фронтальном отделе из эстетических соображений, более прочные — в боковом из-за жевательной нагрузки. Какая разновидность будет использована, планируется совместно с лабораторией.</p>
<h2>В каких случаях она рассматривается?</h2>
<ul>
<li>Зубы со значительной утратой тканей, которые невозможно достаточно укрепить пломбой</li>
<li>Зубы после лечения корневых каналов с повышенным риском перелома</li>
<li>Передние зубы, изменение цвета и формы которых планируется реставрационным путём</li>
<li>Планы мостовидных протезов, когда лунка восполняется с опорой на соседние зубы</li>
<li>Люди с аллергией на металлы в анамнезе</li>
<li>Планирование протеза на импланте — подробнее см. <a href="/ru/dental-implant-tedavisi/">Дентальная имплантация</a></li>
</ul>
<h2>Разница между цирконием и e.max</h2>
<table>
<thead><tr><th>Критерий</th><th>Цирконий</th><th>E.max (дисиликат лития)</th></tr></thead>
<tbody>
<tr><td>Строение</td><td>Каркас из диоксида циркония, при необходимости слой керамики</td><td>Цельная стеклокерамика</td></tr>
<tr><td>Прозрачность</td><td>Различается в зависимости от разновидности; есть очень прозрачные типы</td><td>Как правило, более прозрачен</td></tr>
<tr><td>Прочность</td><td>Более высокая прочность на излом</td><td>Ниже; в протяжённых мостах не предпочитается</td></tr>
<tr><td>Типичное применение</td><td>Боковой отдел, мосты, конструкции на имплантах</td><td>Одиночный зуб во фронтальном отделе, виниры</td></tr>
</tbody>
</table>
<p>Сравнение — не рейтинг превосходства. В одной и той же полости рта во фронтальном отделе может планироваться один материал, а в боковом — другой. О целостном эстетическом планировании см. страницу <a href="/ru/gulus-tasarimi/">Индивидуальный дизайн улыбки</a>.</p>
<h2>Подготовка и этапы работы</h2>
<ol>
<li><strong>Осмотр и планирование.</strong> Оцениваются здоровье дёсен, кариес, смыкание, привычка сжимать зубы и скрежетать ими и сохранившиеся здоровые ткани.</li>
<li><strong>Предварительная подготовка.</strong> Устраняются имеющиеся кариес и проблемы дёсен; при необходимости завершается лечение корневых каналов.</li>
<li><strong>Препарирование зуба и слепок.</strong> Зуб обтачивается ровно настолько, насколько требует выбранный материал; снимается слепок или выполняется цифровое сканирование.</li>
<li><strong>Временная реставрация.</strong> На время работы лаборатории зуб защищён, и форма проходит проверку.</li>
<li><strong>Примерка и фиксация.</strong> После контроля прилегания, смыкания и цвета коронка фиксируется.</li>
<li><strong>Контрольный осмотр.</strong> В первые недели оцениваются прилегание и реакция десны.</li>
</ol>
<h2>Совместимость с десной и уход</h2>
<p>Долгосрочный результат коронки зависит не столько от материала, сколько от точности краевого прилегания и ежедневного ухода. Если участок, где край коронки встречается с десной, не очищается, там могут развиться воспаление и изменение цвета. Поэтому использование межзубных ёршиков или нити, очищение под промежуточной частью моста и регулярные осмотры входят в состав лечения.</p>
<p>У людей с привычкой сжимать зубы и скрежетать ими может встать вопрос о ночной каппе. Такие привычки, как раскалывание зубами твёрдой скорлупы или разгрызание льда, повышают риск перелома и у собственного зуба, и у реставрации.</p>
<h2>Ограничения, о которых нужно знать</h2>
<p>Циркониевая коронка требует обтачивания части тканей зуба; это необратимое вмешательство. Поэтому сначала рассматриваются варианты с меньшей утратой тканей (пломба, онлей, винир). Если планируется отбеливание, важна очерёдность, чтобы цвет коронки можно было подобрать под результат; подробности — на странице <a href="/ru/dis-beyazlatma/">Отбеливание зубов</a>.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Сколько служит циркониевая коронка?</strong><br>Срок индивидуален. Определяющими являются краевое прилегание, здоровье дёсен, жевательная нагрузка, привычка сжимать зубы и ежедневный уход. Обещать определённый срок службы нельзя.</p>
<p><strong>Бывает ли чувствительность после установки коронки?</strong><br>В первые дни возможна чувствительность к горячему и холодному, которая, как правило, проходит. При нарастающей или длительной боли требуется контроль.</p>
<p><strong>Меняется ли цвет коронки со временем?</strong><br>Собственный цвет диоксида циркония не осветляется отбеливанием, и коронка не окрашивается от кофе и чая так, как собственный зуб. Скопившийся на поверхности налёт можно удалить профессиональной чисткой.</p>
<p><strong>Всем ли зубам делают циркониевые коронки?</strong><br>Нет. Если сохранившихся здоровых тканей достаточно, сначала рассматриваются варианты с меньшей утратой тканей, такие как пломба или онлей.</p>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт решение об изготовлении коронки принимается после совместной оценки здоровья дёсен, смыкания и сохранившихся здоровых тканей.</p>
<p><a href="/ru/zirkonyum-dis-kaplama/">Циркониевые коронки</a> &middot; <a href="/ru/estetik/">Эстетическая стоматология</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'Что такое циркониевая коронка, в каких случаях она рассматривается, чем отличается от e.max? Этапы подготовки, совместимость с десной и требования к уходу.',
'RU' FROM blogs WHERE link = 'zirkonyum-dis-kaplama-nedir--avantajlari-nelerdir';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'Ранние признаки заболеваний дёсен и их лечение',
'<p>Заболевания дёсен чаще всего начинаются безболезненно. На первой стадии это может быть кровоточивость, заметная только при чистке зубов; поэтому её замечают с опозданием. Между тем на раннем этапе картина в значительной мере обратима. Когда процесс заходит дальше, затрагивается костная ткань, удерживающая зуб, и потеря становится необратимой.</p>
<h2>Каковы ранние признаки?</h2>
<ul>
<li><strong>Кровоточивость.</strong> Кровоточивость при чистке зубов или использовании нити — самый частый первый признак. Здоровая десна при чистке не кровоточит.</li>
<li><strong>Покраснение и отёчность.</strong> Здоровая десна бледно-розовая и плотная. Ярко-красный, отёчный и рыхлый вид — признак воспаления.</li>
<li><strong>Рецессия десны.</strong> Зубы выглядят удлинившимися, обнажается поверхность корня, что сопровождается чувствительностью.</li>
<li><strong>Неприятный запах изо рта.</strong> Бактерии, скапливающиеся в десневом кармане, могут способствовать стойкому неприятному запаху.</li>
<li><strong>Появление промежутков между зубами.</strong> Смещение зубов, образование щелей между ними или изменение смыкания.</li>
<li><strong>Подвижность.</strong> На поздней стадии зуб подвижен; это показывает, что опорной кости стало меньше.</li>
</ul>
<h2>Разница между гингивитом и пародонтитом</h2>
<table>
<thead><tr><th></th><th>Гингивит (воспаление десны)</th><th>Пародонтит</th></tr></thead>
<tbody>
<tr><td>Поражаемые ткани</td><td>Только десна</td><td>Десна + соединительная ткань + опорная кость</td></tr>
<tr><td>Потеря кости</td><td>Нет</td><td>Есть</td></tr>
<tr><td>Обратимость</td><td>При надлежащем лечении и уходе в значительной мере обратим</td><td>Утраченная кость сама не восстанавливается; останавливают прогрессирование</td></tr>
<tr><td>Типичные находки</td><td>Кровоточивость, покраснение, отёчность</td><td>Увеличение глубины карманов, рецессия, подвижность</td></tr>
</tbody>
</table>
<p>Это различие устанавливается при осмотре: измеряется глубина карманов, оценивается край десны и при необходимости по рентгеновскому снимку определяется уровень кости. Решение не принимается по одному отдельному признаку.</p>
<h2>Факторы, повышающие риск</h2>
<p>Основной фактор — недостаточный контроль налёта. Кроме того, картину могут утяжелять курение, неконтролируемый диабет, некоторые препараты, периоды гормональных изменений, дыхание через рот, плохо прилегающие края реставраций и наследственная предрасположенность. Во время беременности десна кровоточит легче; об этом периоде см. страницу <a href="/ru/hamilelikte-dis-tedavisi/">Лечение зубов при беременности</a>.</p>
<h2>Как проходит лечение?</h2>
<ol>
<li><strong>Оценка.</strong> Измерение карманов, индекс кровоточивости, рецессия, подвижность и при необходимости рентген.</li>
<li><strong>Начальное лечение.</strong> Удаление зубных отложений и сглаживание поверхности корня; пересмотр привычек гигиены полости рта.</li>
<li><strong>Повторная оценка.</strong> Обычно через несколько недель измеряется реакция тканей. У большинства людей этого этапа достаточно.</li>
<li><strong>При необходимости хирургический этап.</strong> Если глубокие карманы сохраняются, рассматриваются хирургические варианты.</li>
<li><strong>Поддерживающий период.</strong> Осмотры с индивидуально определённым интервалом; на этом этапе выявляется рецидив заболевания.</li>
</ol>
<p><strong>Об антибиотиках:</strong> антибиотик не заменяет механическое удаление налёта и зубного камня под десной. Необходимость в нём оценивается отдельно.</p>
<h2>Что можно делать дома</h2>
<p>Чистить зубы дважды в день мягкой щёткой, направляя её к краю десны, раз в день очищать межзубные промежутки (нить или ёршик), отказаться от курения и соблюдать интервал контрольных осмотров. Заметив кровоточивость, нужно не сокращать чистку, а исправлять технику; неочищенный участок поддерживает воспаление.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Проходит ли кровоточивость дёсен сама?</strong><br>Пока не устранена причина — нет. Пока продолжается скопление налёта, продолжается и воспаление. Кровоточивость, не проходящую в течение нескольких дней, следует оценить.</p>
<p><strong>Стирает ли удаление зубных отложений зубы?</strong><br>Выполненная надлежащей техникой чистка не стирает ткани зуба. Ощущаемая после неё чувствительность связана с обнажением поверхности корня, ранее прикрытой зубным камнем, и обычно проходит.</p>
<p><strong>Восстанавливается ли рецессировавшая десна?</strong><br>Сама по себе нет. При некоторых видах рецессии могут рассматриваться хирургические варианты закрытия; возможность зависит от осмотра.</p>
<p><strong>Как часто мне нужно приходить на осмотр?</strong><br>Интервал определяется индивидуально. У людей с факторами риска частота осмотров увеличивается.</p>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт очерёдность лечения определяется после совместной оценки состояния дёсен, измерения карманов и необходимой визуализации.</p>
<p><a href="/ru/agiz-dis-sagligi/">Здоровье полости рта и зубов</a> &middot; <a href="/ru/dis-curugu-kompozit-dolgu/">Кариес и композитные пломбы</a> &middot; <a href="/ru/ilk-dis-muayenesi-tedavi-planlamasi/">Первый стоматологический осмотр</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'Что означают кровоточивость дёсен, покраснение, рецессия и неприятный запах изо рта? Разница между гингивитом и пародонтитом, этапы лечения и факторы риска.',
'RU' FROM blogs WHERE link = 'dis-eti-hastaliklarinin-erken-belirtileri-ve-tedavi-yontemleri';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'Почему появляется неприятный запах изо рта? Причины и стойкое решение',
'<p>Неприятный запах изо рта (галитоз) — распространённая жалоба, и в большинстве случаев его причина находится в полости рта. Запах обычно возникает из-за летучих соединений серы, которые бактерии образуют при расщеплении белковых остатков. Стойкое решение состоит не в том, чтобы замаскировать запах, а в том, чтобы найти его источник.</p>
<h2>Утренний запах и стойкий запах — не одно и то же</h2>
<p>Во время сна выделение слюны снижается и бактерии размножаются активнее; поэтому ощущаемый утром запах — обычное явление, проходящее после чистки зубов. А вот запах, который сохраняется в течение дня и заметно не уменьшается после чистки, следует обследовать.</p>
<h2>Причины в полости рта</h2>
<ul>
<li><strong>Бактериальный налёт на спинке языка.</strong> Значительная часть запахов, исходящих из полости рта, связана с задней частью языка.</li>
<li><strong>Заболевание дёсен.</strong> Бактерии, скапливающиеся в десневых карманах, способствуют стойкому запаху. Подробнее: <a href="/ru/blog/dis-eti-hastaliklarinin-erken-belirtileri-ve-tedavi-yontemleri">ранние признаки заболеваний дёсен</a>.</li>
<li><strong>Кариес и сломанные зубы.</strong> В недоступных для очищения полостях скапливаются пища и бактерии.</li>
<li><strong>Плохо прилегающие реставрации и протезы.</strong> Краевые щели и неочищенные поверхности протезов могут быть источником запаха.</li>
<li><strong>Сухость во рту.</strong> Некоторые препараты, дыхание через рот и недостаточное питьё уменьшают количество слюны; слюна — естественное очищающее средство полости рта.</li>
<li><strong>Ретинированный или частично прорезавшийся зуб мудрости.</strong> Участок, оставшийся под десной, невозможно очистить. Подробнее: <a href="/ru/agiz-cerrahisi-uygulamalari/">Операции в полости рта</a>.</li>
</ul>
<h2>Причины вне полости рта</h2>
<p>Запах могут вызывать также синусит, камни миндалин, инфекции верхних дыхательных путей, рефлюкс и некоторые обменные состояния. Если оценка полости рта не выявляет отклонений, эти возможности выходят на первый план и рассматриваются совместно с соответствующим медицинским направлением.</p>
<h2>Питание и привычки</h2>
<p>Запах таких продуктов, как чеснок и лук, переносится с кровью в лёгкие, поэтому он не исчезает полностью после чистки зубов; он сам уменьшается в течение нескольких часов. Курение и оставляет собственный запах, и повышает риск заболеваний дёсен. При диетах с очень низким содержанием углеводов во рту может ощущаться иной запах.</p>
<h2>Порядок действий на приёме</h2>
<table>
<thead><tr><th>Этап</th><th>Что делается</th></tr></thead>
<tbody>
<tr><td>Анамнез</td><td>Длительность запаха, его динамика в течение дня, принимаемые препараты, сухость во рту, курение и привычки питания</td></tr>
<tr><td>Осмотр полости рта</td><td>Состояние дёсен, глубина карманов, кариес, края реставраций, прилегание протезов, спинка языка</td></tr>
<tr><td>Визуализация</td><td>При необходимости; при подозрении на ретинированный зуб, инфекцию у верхушки корня или невидимый глазом кариес</td></tr>
<tr><td>Очерёдность лечения</td><td>Сначала источник воспаления и инфекции; затем реставрационное исправление недоступных для очищения участков; после этого порядок ухода</td></tr>
</tbody>
</table>
<h2>Что помогает добиться стойкого результата</h2>
<ol>
<li>Чистка зубов дважды в день и очищение межзубных промежутков раз в день</li>
<li>Бережное очищение задней части спинки языка</li>
<li>Завершение лечения дёсен и соблюдение интервала контрольных осмотров</li>
<li>Устранение недоступных для очищения кариозных полостей, сколов и плохо прилегающих реставраций</li>
<li>Достаточное питьё; если сухость во рту сохраняется, выяснение её причины</li>
<li>Отказ от курения</li>
</ol>
<p>Ополаскиватели могут ненадолго подавить запах, но не устраняют причину. Длительное применение некоторых спиртосодержащих ополаскивателей может усиливать сухость во рту.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Почему я не чувствую собственный запах изо рта?</strong><br>Обоняние приспосабливается к запаху, которому оно постоянно подвергается. Поэтому отзыв близкого человека или врачебная оценка надёжнее.</p>
<p><strong>Я чищу зубы, но запах сохраняется — почему?</strong><br>Возможно, щётка недостаточно достаёт до спинки языка, десневых карманов и межзубных промежутков. Источником может быть и недоступный для очищения кариес или ретинированный зуб.</p>
<p><strong>Может ли запах изо рта исходить от желудка?</strong><br>Может, но это встречается реже, чем принято считать. Сначала оцениваются причины в полости рта.</p>
<p><strong>Стоит ли пользоваться скребком для языка?</strong><br>Очищение задней части спинки языка может уменьшить запах. Делать это следует без сильного нажима, не провоцируя рвотный рефлекс.</p>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт оценка неприятного запаха изо рта проводится с совместным исследованием состояния дёсен, кариеса, краёв реставраций и спинки языка.</p>
<p><a href="/ru/agiz-dis-sagligi/">Здоровье полости рта и зубов</a> &middot; <a href="/ru/ilk-dis-muayenesi-tedavi-planlamasi/">Первый стоматологический осмотр</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'Причины неприятного запаха изо рта внутри и вне полости рта, роль языка, сухость во рту, разница между утренним и стойким запахом и порядок действий на приёме.',
'RU' FROM blogs WHERE link = 'agiz-kokusu-neden-olur--kalici-cozum-icin-neler-yapilabilir';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'Что такое Hollywood Smile? Что стоит за этим понятием?',
'<p>«Hollywood Smile» — не медицинское название лечения. Это популярное выражение, описывающее вид очень светлых, ровно стоящих и симметричных зубов. За ним стоит не одна процедура, а планирование, различное для каждого человека. Поэтому правильно начинать не с того, чтобы «сделать Hollywood Smile», а с того, чтобы понять, что и с помощью каких вмешательств изменится.</p>
<h2>Что может включать это понятие?</h2>
<ul>
<li>Отбеливание зубов — если задача только в изменении цвета. Подробнее: <a href="/ru/dis-beyazlatma/">Отбеливание зубов</a></li>
<li>Композитные реставрации — небольшая коррекция формы, краёв и промежутков</li>
<li>Виниры (керамические накладки)</li>
<li>Коронки, например <a href="/ru/zirkonyum-dis-kaplama/">циркониевые</a></li>
<li>Коррекция уровня десны</li>
<li>Ортодонтическое лечение — когда основная причина в положении зубов</li>
<li>Восполнение отсутствующего зуба — <a href="/ru/dental-implant-tedavisi/">Дентальная имплантация</a></li>
</ul>
<p>Все эти вмешательства вместе не требуются. Кому-то достаточно чистки и отбеливания; у кого-то основная проблема в положении зубов, поэтому вместо реставрационного вмешательства обсуждается ортодонтическое лечение.</p>
<h2>Как планируется естественный вид?</h2>
<p>Естественный результат связан не столько с белизной отдельных зубов, сколько с гармонией целого. При планировании вместе оцениваются:</p>
<table>
<thead><tr><th>Критерий</th><th>Почему это важно</th></tr></thead>
<tbody>
<tr><td>Линия лица и улыбки</td><td>Отношение краёв зубов к линии нижней губы определяет естественность</td></tr>
<tr><td>Срединная линия</td><td>Отношение срединной линии зубов к срединной линии лица</td></tr>
<tr><td>Пропорции зубов</td><td>Соотношение длины и ширины передних зубов между собой</td></tr>
<tr><td>Уровень десны</td><td>Сколько десны видно при улыбке и насколько симметрично она расположена</td></tr>
<tr><td>Цвет и прозрачность</td><td>Однотонная белизна выглядит искусственно; прозрачность у режущего края придаёт естественность</td></tr>
<tr><td>Смыкание и функция</td><td>Эстетический результат не должен нарушать жевание и речь</td></tr>
</tbody>
</table>
<p>На этапе планирования могут использоваться фотографии, цифровое сканирование и при необходимости временная примерка во рту. Цель — увидеть результат вместе до перехода к окончательному вмешательству. Процесс подробно описан на странице <a href="/ru/gulus-tasarimi/">Индивидуальный дизайн улыбки</a>.</p>
<h2>Сначала здоровье, потом эстетика</h2>
<p>Если есть кариес, воспаление дёсен, инфекция у верхушки корня или проблема смыкания, эстетическое вмешательство поверх них не выполняется. У края реставрации, установленной при продолжающемся воспалении дёсен, вскоре могут появиться изменение цвета и рецессия. Поэтому очерёдность такова: контроль неотложных состояний и инфекции, базовое лечение дёсен и кариеса, затем эстетический этап. О процессе в целом см. <a href="/ru/tedavi-plani-ve-surec/">План лечения и его ход</a>.</p>
<h2>Вопросы, которые стоит задать перед решением</h2>
<ul>
<li>Какие вмешательства предлагаются в моём случае и почему?</li>
<li>Сколько тканей зуба потребуется обточить? Это обратимо?</li>
<li>Есть ли альтернатива с меньшей утратой тканей?</li>
<li>Могу ли я увидеть результат до окончательного вмешательства?</li>
<li>Какой уход и режим контрольных осмотров потребуются потом?</li>
<li>Могу ли я получить сведения об используемом материале и лаборатории?</li>
</ul>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Обязательно ли нужны коронки для Hollywood Smile?</strong><br>Нет. Кому-то может быть достаточно отбеливания и небольшой композитной коррекции. Поскольку коронка требует большего обтачивания тканей, её рассматривают после оценки остальных вариантов.</p>
<p><strong>Насколько белыми должны быть зубы?</strong><br>Мерилом являются личные предпочтения и черты лица. Однотонная белизна, не сочетающаяся с цветом кожи и глаз, выглядит искусственно.</p>
<p><strong>Является ли результат постоянным?</strong><br>Срок службы реставраций зависит от краевого прилегания, жевательной нагрузки, привычки сжимать зубы и ежедневного ухода. Точный срок не обещается; нужны регулярные осмотры.</p>
<p><strong>Иначе ли проходит процесс для приезжающих из-за рубежа?</strong><br>Планирование то же самое. Поскольку между этапами есть время на заживление и работу лаборатории, график обсуждается с самого начала.</p>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт эстетическое планирование проводится с совместной оценкой здоровья дёсен, смыкания, сохранившихся здоровых тканей и ожиданий человека.</p>
<p><a href="/ru/estetik/">Эстетическая стоматология</a> &middot; <a href="/ru/gulus-tasarimi/">Индивидуальный дизайн улыбки</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'Hollywood Smile — не название лечения, а эстетическое описание. Какие вмешательства оно может включать, как планируется естественный вид, на что обратить внимание?',
'RU' FROM blogs WHERE link = 'hollywood-smile-nedir--mukemmel-guluse-giden-yol';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'Что оценивается на первом осмотре перед имплантацией?',
'<p>Решение об имплантации не сводится к установке винта вместо отсутствующего зуба. Первый осмотр — это оценка, в которой совместно рассматриваются состояние кости, здоровье дёсен, смыкание, общая история здоровья и ожидания человека. Принятые на этом этапе решения напрямую определяют долгосрочный результат лечения.</p>
<h2>С чего начинается осмотр?</h2>
<p>Первый шаг — выслушать жалобу и ожидания: когда был потерян зуб, проводились ли ранее вмешательства в этой области, есть ли трудности при жевании, есть ли эстетические опасения. Затем собирается медицинский анамнез. Выясняются системные заболевания, регулярно принимаемые препараты, аллергии и перенесённые операции.</p>
<p>Некоторые группы препаратов и неконтролируемые системные состояния могут изменить хирургический план. Поэтому особо уточняются приём отдельных препаратов для лечения потери костной массы, разжижающих кровь средств и наличие неконтролируемого диабета. Ни один препарат пациент не отменяет по собственному решению; при необходимости запрашивается мнение наблюдающего врача.</p>
<h2>Оценка в полости рта</h2>
<ul>
<li><strong>Здоровье дёсен.</strong> При активном воспалении оно устраняется до имплантологической операции.</li>
<li><strong>Состояние соседних зубов.</strong> Кариес, сколы, негерметичные реставрации или инфекция у верхушки корня могут изменить очерёдность.</li>
<li><strong>Размеры промежутка.</strong> Ширина беззубого участка и расстояние до зуба-антагониста определяют возможный размер импланта.</li>
<li><strong>Толщина десны и полоса прикреплённой десны.</strong> Важны для долгосрочного здоровья дёсен.</li>
<li><strong>Смыкание и характер жевания.</strong> Привычка сжимать зубы и скрежетать ими увеличивает нагрузку на протез на импланте.</li>
<li><strong>Открывание рта.</strong> Влияет на хирургический доступ, особенно в боковом отделе.</li>
<li><strong>Привычки гигиены полости рта и курение.</strong> Определяют заживление и долгосрочный результат.</li>
</ul>
<h2>Зачем нужна визуализация?</h2>
<p>Высоту, ширину и плотность кости нельзя оценить на глаз. Кроме того, без знания положения нижнечелюстного канала на нижней челюсти и полости пазухи на верхней безопасное планирование невозможно. Поэтому назначаются панорамный снимок и в большинстве случаев трёхмерная визуализация.</p>
<table>
<thead><tr><th>Исследование</th><th>Что оно показывает</th></tr></thead>
<tbody>
<tr><td>Панорамный снимок</td><td>Общая картина, оставшиеся фрагменты корней, подозрение на кисту, состояние соседних зубов</td></tr>
<tr><td>Трёхмерная визуализация</td><td>Ширина и плотность кости, положение нервного канала и дна пазухи, измерения на срезах</td></tr>
<tr><td>Цифровое сканирование / модель</td><td>Характер смыкания, положение, в котором имплант должен стоять с ортопедической точки зрения</td></tr>
</tbody>
</table>
<p>Компьютерная томография не назначается автоматически каждому пациенту. Ожидаемый диагностический вклад оценивается вместе с лучевой нагрузкой; если имеющиеся записи актуальны и достаточны, повторные не назначаются. Этот принцип подробно изложен на странице <a href="/ru/ilk-dis-muayenesi-tedavi-planlamasi/">Первый стоматологический осмотр и планирование лечения</a>.</p>
<h2>Планирование от протеза в обратном порядке</h2>
<p>Правильный подход состоит в том, чтобы устанавливать имплант не туда, где больше всего кости, а туда, где должен находиться протез. Поэтому планирование начинается с итогового вида и характера жевания и идёт в обратном направлении. Если кости в этом положении недостаточно, вариантами могут быть имплант другого размера, установка под углом, вмешательства для увеличения объёма кости или иное ортопедическое решение.</p>
<h2>Можно ли установить имплант сразу?</h2>
<p>В некоторых случаях имплант может быть установлен в то же посещение, что и удаление зуба; в других ожидают заживления кости. Решение зависит от наличия инфекции, целостности стенок лунки, качества кости и первичной стабильности импланта. Установка несъёмных зубов в тот же день также подходит не в каждом случае.</p>
<h2>Что обсуждается в конце осмотра?</h2>
<ol>
<li>Клинические данные и результат визуализации</li>
<li>Предлагаемый подход и его обоснование</li>
<li>Альтернативы (мост, частичный протез, наблюдение за промежутком) и различия между ними</li>
<li>Этапы, предполагаемое число приёмов и ожидаемые сроки заживления</li>
<li>Существенные риски и возможные осложнения</li>
<li>Ожидаемое развитие событий без лечения</li>
<li>Последующий порядок ухода и контрольных осмотров</li>
</ol>
<p>О том, как план передаётся в письменном виде и как вас информируют при его изменении, см. страницу <a href="/ru/tedavi-plani-ve-surec/">План лечения и его ход</a>.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Если кости недостаточно, имплантация невозможна?</strong><br>Недостаток сам по себе не является препятствием. Могут рассматриваться вмешательства для увеличения объёма кости; возможность определяется местом и величиной дефицита.</p>
<p><strong>Что взять с собой на осмотр?</strong><br>Имеющиеся прежние рентгеновские и томографические снимки, список принимаемых препаратов, сведения об известных заболеваниях и аллергиях. Если имплантация уже проводилась — карту с данными о марке и размере.</p>
<p><strong>Я курю — влияет ли это на оценку?</strong><br>Да. Курение может неблагоприятно влиять на заживление и долгосрочный результат. Это тема, которую нужно открыто обсудить при планировании.</p>
<p><strong>Принимается ли решение за один приём?</strong><br>Чаще всего после визуализации и лабораторной оценки проводится вторая консультация. Если нет неотложного состояния, естественно, что вы возьмёте время на обдумывание.</p>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт оценка для имплантации проводится с совместным выполнением клинического осмотра, необходимой визуализации и ортопедического планирования.</p>
<p><a href="/ru/dental-implant-tedavisi/">Дентальная имплантация</a> &middot; <a href="/ru/implant/">Лечение имплантами</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'Как перед имплантацией оцениваются кость, дёсны, смыкание и медицинский анамнез? Какая визуализация и зачем назначается, что определяет решение?',
'RU' FROM blogs WHERE link = 'implant-tedavisinde-ilk-muayenede-neler-degerlendirilir';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'На что обратить внимание в период заживления после имплантации?',
'<p>Результат имплантологической операции определяется не только в кресле. Уход в первые дни, режим питания и соблюдение контрольных приёмов напрямую влияют на процесс срастания кости с имплантом. Эта статья рассказывает, чего ожидать в период заживления и на что обратить внимание; она не заменяет личных указаний вашего врача.</p>
<h2>Первые 24 часа</h2>
<ul>
<li>Слегка прикусывайте вложенный тампон в течение времени, указанного врачом.</li>
<li>Охлаждение области вмешательства снаружи может помочь уменьшить отёк.</li>
<li>В первый день не полощите рот, не сплёвывайте и не пейте через трубочку. Это может сместить кровяной сгусток.</li>
<li>Не курите. Курение — один из наиболее известных факторов, неблагоприятно влияющих на заживление.</li>
<li>Отдыхайте, держа голову немного приподнятой; избегайте тяжёлых нагрузок и работы, требующей наклонов.</li>
<li>Принимайте препараты в порядке, назначенном врачом; не добавляйте и не отменяйте ничего самостоятельно.</li>
</ul>
<h2>Питание</h2>
<p>В первые дни предпочтительна мягкая и тёплая пища. Очень горячие напитки, твёрдая и хрустящая еда, продукты с косточками и мелкими зёрнами могут раздражать область вмешательства. Перенести жевание на другую сторону — самый простой способ защитить эту область. Достаточное питьё помогает заживлению; алкоголя следует избегать.</p>
<h2>Гигиена полости рта</h2>
<p>Полностью отказываться от ухода неправильно; скопление налёта затрудняет заживление. Остальные участки полости рта продолжают чистить как обычно. Область вмешательства очищают бережно очень мягкой щёткой, начиная со времени, которое назовёт ваш врач. Применение ополаскивателя и его сроки определяет врач.</p>
<h2>Что нормально, а что нет?</h2>
<table>
<thead><tr><th>Проявление</th><th>Ожидаемое течение</th><th>Когда нужно позвонить в клинику</th></tr></thead>
<tbody>
<tr><td>Отёк</td><td>Нарастает в первые 2–3 дня, затем уменьшается</td><td>Если он продолжает нарастать, затрудняет глотание или дыхание</td></tr>
<tr><td>Боль</td><td>В первые дни контролируется рекомендованным препаратом</td><td>Боль, которая нарастает несмотря на препарат или будит ночью</td></tr>
<tr><td>Сочащееся кровотечение</td><td>Возможно в первые часы</td><td>Неостанавливающееся, активное кровотечение</td></tr>
<tr><td>Синяк</td><td>Бывает у части людей, проходит сам</td><td>Быстро распространяющийся синяк, сопровождающийся болью</td></tr>
<tr><td>Температура</td><td>Не ожидается</td><td>Высокая температура, слабость, неприятный запах или привкус</td></tr>
<tr><td>Онемение</td><td>Несколько часов под действием анестезии</td><td>Онемение губы, подбородка или языка, сохраняющееся и на следующий день</td></tr>
</tbody>
</table>
<h2>Период срастания (остеоинтеграции)</h2>
<p>Срастание импланта с костью — биологический процесс, занимающий недели. Срок зависит от качества кости, области установки импланта, наличия дополнительных вмешательств и индивидуальной реакции заживления. В этот период важно не перегружать область.</p>
<p>Если вы пользуетесь временным протезом, его прилегание настраивает врач. Если какой-то участок давит или натирает, не пытайтесь исправить это сами; приходите на осмотр. Нагрузка до завершения срастания может ухудшить результат.</p>
<h2>Что защищает имплант в долгосрочной перспективе?</h2>
<p>Имплант не разрушается кариесом, но десна и кость вокруг него могут заболеть. Картина, похожая на воспаление десны у собственного зуба, встречается и вокруг импланта, а при прогрессировании уменьшает опорную кость. Способ защиты неизменен: регулярная и правильная гигиена, очищение межзубных промежутков, отказ от курения и соблюдение интервала контрольных осмотров.</p>
<p>У людей с привычкой сжимать зубы и скрежетать ими может встать вопрос о ночной каппе. На осмотрах оцениваются десна вокруг импланта, ослабление винта, износ протеза и характер смыкания.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Сколько длится заживление?</strong><br>Первичное заживление мягких тканей занимает от нескольких дней до нескольких недель; срастание с костью длится дольше. Точный срок индивидуален и оценивается на контрольных приёмах.</p>
<p><strong>Обязательно ли принимать антибиотик?</strong><br>Необходимость определяет врач. Антибиотик не заменяет гигиену и хирургический уход.</p>
<p><strong>Можно ли заниматься спортом?</strong><br>Лёгкая повседневная активность обычно не является проблемой; тяжёлые нагрузки, контактные виды спорта и движения с наклонами в первые дни откладывают.</p>
<p><strong>Мне кажется, что имплант шатается — это нормально?</strong><br>Нет. Если вы чувствуете подвижность, следует без промедления прийти на осмотр.</p>
<p><strong>Когда снимают швы?</strong><br>Это зависит от вида шовного материала; часть из них рассасывается сама. Приём планирует ваш врач.</p>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт интервал контрольных осмотров после имплантации определяется совместной оценкой выполненного вмешательства, состояния кости и индивидуальной реакции заживления.</p>
<p><a href="/ru/dental-implant-tedavisi/">Дентальная имплантация</a> &middot; <a href="/ru/agiz-cerrahisi-uygulamalari/">Операции в полости рта</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'Первые 24 часа после имплантации, питание, гигиена полости рта и период срастания. Какое проявление нормально, а когда нужно позвонить в клинику?',
'RU' FROM blogs WHERE link = 'implant-sonrasi-iyilesme-doneminde-nelere-dikkat-edilir';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'Когда может потребоваться синус-лифтинг?',
'<p>Самое частое препятствие при планировании импланта в боковом отделе верхней челюсти — недостаточная высота кости. Причина в том, что над зубом находится воздушная полость, называемая верхнечелюстной пазухой, а кость в этой области после потери зуба со временем убывает. Поднятие дна пазухи (синус-лифтинг) — вмешательство, цель которого увеличить объём кости, чтобы имплант можно было установить безопасно.</p>
<h2>Почему кость в этой области убывает?</h2>
<p>После удаления зуба кость в этой области со временем рассасывается, поскольку исчезает приходившаяся на неё жевательная нагрузка. Кроме того, в боковом отделе верхней челюсти полость пазухи может расширяться книзу. Когда оба фактора складываются, высоты, необходимой для импланта, может не остаться. Поэтому важно, сколько времени прошло с момента потери зуба.</p>
<h2>Как принимается решение?</h2>
<p>Решение не принимается по одному лишь панорамному снимку. С помощью трёхмерной визуализации, позволяющей делать измерения на срезах, оцениваются оставшаяся высота кости, её ширина и форма дна пазухи. Кроме того, проверяется, здорова ли пазуха; при активном синусите вмешательство откладывают и сначала занимаются этим состоянием.</p>
<table>
<thead><tr><th>Что оценивается</th><th>Почему это важно</th></tr></thead>
<tbody>
<tr><td>Оставшаяся высота кости</td><td>Определяет выбор метода и возможность выполнить вмешательство в то же посещение, что и имплантацию</td></tr>
<tr><td>Ширина кости</td><td>Даже при достаточной высоте при недостаточной ширине может потребоваться дополнительное вмешательство</td></tr>
<tr><td>Анатомия дна пазухи</td><td>Перегородки и неровности меняют хирургический план</td></tr>
<tr><td>Состояние пазухи</td><td>При активной инфекции или хроническом синусите сроки меняются</td></tr>
<tr><td>Общее состояние здоровья и курение</td><td>Влияют на заживление и успех</td></tr>
</tbody>
</table>
<h2>Два основных подхода</h2>
<p><strong>Закрытый метод (крестальный доступ).</strong> Дно пазухи контролируемо приподнимается через ложе, подготовленное для импланта. Метод может быть предпочтителен, если оставшаяся высота кости выше определённого уровня и удаётся обеспечить первичную стабильность импланта. Чаще всего выполняется в то же посещение, что и имплантация.</p>
<p><strong>Открытый метод (латеральное окно).</strong> Через окно, сформированное в кости сбоку, поднимают слизистую пазухи и в образовавшееся пространство помещают костнозамещающий материал. Применяется, когда кости меньше или требуется обработать обширный участок. Имплант может быть установлен в то же посещение, либо ожидают созревания кости.</p>
<p>Какой метод будет использован, определяется по измерениям; один не превосходит другой. Об месте этого вмешательства в хирургии полости рта см. страницу <a href="/ru/agiz-cerrahisi-uygulamalari/">Операции в полости рта</a>.</p>
<h2>Период заживления</h2>
<p>После вмешательства в течение нескольких дней ожидаются отёк и чувствительность. В этот период нужно не сморкаться с усилием, при чихании держать рот открытым, не пользоваться трубочкой и на указанный врачом срок отложить ситуации с перепадом давления, например авиаперелёты. Особо подчёркивается необходимость воздержаться от курения.</p>
<p>Небольшие кровянистые выделения из носа возможны в первые дни. При нарастающей боли, высокой температуре, неприятном запахе, сохраняющейся односторонней заложенности носа или выделениях из области вмешательства следует обратиться в клинику.</p>
<h2>Есть ли альтернативы?</h2>
<p>Синус-лифтинг не единственный путь в каждом случае. В зависимости от оставшейся кости могут рассматриваться более короткие импланты, установка импланта под углом, опора из соседней области или частичный протез вместо несъёмного. У каждого варианта свои условия и ограничения; решение принимается вместе с измерениями и ортопедическим планом.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Синус-лифтинг — болезненное вмешательство?</strong><br>Вмешательство проводится под местной анестезией. После него в течение нескольких дней ожидаются отёк и чувствительность; задача — чтобы они оставались контролируемыми.</p>
<p><strong>Когда после вмешательства устанавливают имплант?</strong><br>Если оставшейся кости достаточно, его можно установить в то же посещение. Если недостаточно, ожидают определённое время для созревания костнозамещающего материала; этот срок зависит от человека и используемого материала.</p>
<p><strong>У меня синусит — можно ли проводить вмешательство?</strong><br>При активной инфекции — нет. Сначала занимаются этим состоянием и ждут, пока пазуха станет здоровой.</p>
<p><strong>Какой костнозамещающий материал используется?</strong><br>Возможны собственная кость пациента, готовые костнозамещающие материалы или их сочетание. Какой материал будет использован и почему, вам разъяснят; вы вправе об этом спросить.</p>
<p><strong>Что будет, если вмешательство окажется неуспешным?</strong><br>Хотя и редко, возможны разрыв мембраны, инфекция или отсутствие ожидаемого созревания материала. В таких случаях обсуждаются выжидание, повторная оценка или иной ортопедический план.</p>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт решение о поднятии дна пазухи принимается после совместной оценки трёхмерных измерений, состояния пазухи и ортопедического плана.</p>
<p><a href="/ru/cerrahi/">Челюстно-лицевая хирургия</a> &middot; <a href="/ru/dental-implant-tedavisi/">Дентальная имплантация</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'Почему при недостатке кости в боковом отделе верхней челюсти поднимают дно пазухи? Закрытый и открытый метод, правила заживления и альтернативы.',
'RU' FROM blogs WHERE link = 'sinus-lifting-ne-zaman-gerekli-olabilir';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'В каких случаях удаляют зуб мудрости?',
'<p>Зубы мудрости (третьи моляры) обычно начинают прорезываться на исходе подросткового возраста и в начале двадцатых годов. Не каждый зуб мудрости создаёт проблемы, и не каждый зуб мудрости удаляют. Решение принимается с учётом положения зуба, вреда, который он наносит окружающим тканям, и имеющихся проявлений.</p>
<h2>Почему он может создавать проблемы?</h2>
<p>Места, отведённого этим зубам в челюстной кости, у большинства людей немного. Зуб, которому не хватает места, не прорезывается полностью, остаётся наклонённым или пребывает ретинированным в кости. Десневой карман вокруг частично прорезавшегося зуба невозможно очистить; скапливающиеся там бактерии приводят к воспалению.</p>
<h2>Случаи, когда рассматривается удаление</h2>
<ul>
<li>Повторяющееся воспаление десны, отёк и боль (перикоронит)</li>
<li>Недоступный для очищения кариес на зубе мудрости или соседнем моляре</li>
<li>Давление на корень соседнего зуба, приводящее к его резорбции</li>
<li>Развитие вокруг него кисты или иной патологии</li>
<li>Образование недоступного для очищения глубокого десневого кармана у соседнего зуба</li>
<li>Прорезывание в положении, травмирующем зуб-антагонист или щёку</li>
<li>Требования планируемого ортодонтического или ортопедического лечения</li>
</ul>
<h2>Случаи, когда удаление не требуется</h2>
<p>Полностью прорезавшийся, соответствующий смыканию, доступный для очищения и не поражённый кариесом зуб мудрости может оставаться во рту. При ретинированных зубах, которые не дают проявлений и вокруг которых нет патологии, может быть предпочтено наблюдение. Наблюдение не означает «забыть»: с определёнными интервалами проводятся клинические и рентгенологические осмотры.</p>
<p>Распространённые убеждения вроде «зубы мудрости нужно удалять всем» или «зубы мудрости искривляют передние зубы» сами по себе не считаются основанием для удаления. Решение опирается на индивидуальные данные.</p>
<h2>На что обращают внимание при оценке?</h2>
<table>
<thead><tr><th>Критерий</th><th>Почему это важно</th></tr></thead>
<tbody>
<tr><td>Положение и наклон зуба</td><td>Определяют хирургическую сложность и влияние на соседний зуб</td></tr>
<tr><td>Форма и число корней</td><td>Меняют план удаления</td></tr>
<tr><td>Близость к нервному каналу на нижней челюсти</td><td>Для оценки риска онемения; при необходимости назначается трёхмерная визуализация</td></tr>
<tr><td>Отношение к пазухе на верхней челюсти</td><td>Влияет на хирургический доступ</td></tr>
<tr><td>Состояние соседнего зуба</td><td>Кариес, резорбция корня или наличие кармана</td></tr>
<tr><td>Общее состояние здоровья и принимаемые препараты</td><td>Сроки и хирургическое планирование</td></tr>
</tbody>
</table>
<h2>Вмешательство и заживление</h2>
<p>Удаление проводится под местной анестезией. При ретинированных зубах может потребоваться отслоить десну и удалить зуб по частям; это не означает, что вмешательство усложняется, — это решение, направленное на сохранение тканей.</p>
<p>В первые дни ожидаются отёк, ограничение открывания рта и чувствительность. В этот период рекомендуются охлаждение, мягкая пища, отказ от курения и от полосканий в первый день. Боль, возникающая из-за смещения кровяного сгустка и обычно нарастающая через несколько дней, требует осмотра.</p>
<p>При нарастающей боли, высокой температуре, затруднении глотания или дыхания, неостанавливающемся кровотечении или сохраняющемся на следующий день онемении губы и подбородка следует без промедления обратиться в клинику. О том, что делать в первые часы, рассказывается на странице <a href="/ru/acil-dis-agrisinda-ilk-24-saat/">Первые 24 часа при острой зубной боли</a>.</p>
<h2>Сроки</h2>
<p>Удаления, выполненные, пока корни ещё не полностью сформированы, обычно проходят легче, и заживление может быть быстрее. Однако это не означает, что каждый бессимптомный зуб нужно удалять в молодом возрасте. Решение принимается путём сопоставления ожидаемой пользы с рисками вмешательства.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Можно ли удалить зубы с обеих сторон за один приём?</strong><br>В некоторых случаях это возможно. Решение принимается с учётом положения зубов, предполагаемой длительности вмешательства и общего состояния человека.</p>
<p><strong>Останется ли онемение после удаления навсегда?</strong><br>У зубов нижней челюсти, расположенных близко к нервному каналу, возможно временное онемение; стойкое встречается редко. Риск заранее оценивается по данным визуализации и разъясняется вам.</p>
<p><strong>Можно ли удалять зуб во время беременности?</strong><br>Несрочные хирургические вмешательства, как правило, откладывают. При неотложном состоянии сроки и подход планируются отдельно; подробности — на странице <a href="/ru/hamilelikte-dis-tedavisi/">Лечение зубов при беременности</a>.</p>
<p><strong>Что будет, если я не удалю зуб?</strong><br>При зубе, дающем проявления или вредящем соседнему зубу, выжидание может привести к прогрессированию кариеса и потере кости. При бессимптомных зубах наблюдение, напротив, может быть подходящим вариантом.</p>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт решение по зубу мудрости принимается с совместным рассмотрением клинического осмотра, рентгенологической оценки и состояния соседних зубов.</p>
<p><a href="/ru/agiz-cerrahisi-uygulamalari/">Операции в полости рта</a> &middot; <a href="/ru/cerrahi/">Челюстно-лицевая хирургия</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'В каких случаях зуб мудрости удаляют, а в каких наблюдают? Критерии оценки, вмешательство, заживление и выбор момента.',
'RU' FROM blogs WHERE link = 'yirmi-yas-disi-hangi-durumlarda-cekilir';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'Всегда ли после лечения корневых каналов нужна коронка?',
'<p>Самый частый вопрос о зубе, лечение корневых каналов которого завершено, звучит так: «Обязательно ли мне теперь делать коронку?» Короткий ответ — нет. Коронка не является автоматическим продолжением лечения корневых каналов. Решение принимается с учётом места зуба во рту, количества сохранившихся здоровых тканей, жевательной нагрузки и риска перелома.</p>
<h2>Главный вопрос не в «каналах», а в том, сколько тканей осталось</h2>
<p>Лечение корневых каналов касается тканей внутри зуба. Хрупким зуб делает чаще всего не само лечение, а те ткани, которые были утрачены до него: глубокий кариес, старая обширная пломба, скол или стираемость. Чем тоньше стали стенки зуба, тем выше риск того, что он расколется при жевании.</p>
<p>Поэтому оценка направлена не на лечение корневых каналов, а на сохранившиеся ткани зуба. Понять, как развивается кариес и что он разрушает, поможет страница <a href="/ru/dis-curugu-kompozit-dolgu/">Кариес и композитные пломбы</a>.</p>
<h2>Боковые и передние зубы — не одно и то же</h2>
<p>Большие и малые коренные зубы несут основную жевательную нагрузку. В этой области сила стремится расколоть зуб в стороны; у бокового зуба с ослабленными стенками чаще всего встаёт вопрос о перекрывающей реставрации (онлей или коронка).</p>
<p>У передних зубов нагрузка меньше, а полость доступа небольшая. Если сохранившихся тканей достаточно, хорошо выполненная композитная пломба может служить долго. Решение о коронке на переднем зубе чаще связано не с риском перелома, а с ожиданиями по цвету и форме.</p>
<h2>Варианты и где они уместны</h2>
<table>
<thead><tr><th>Реставрация</th><th>Когда она рассматривается</th><th>На что обращают внимание</th></tr></thead>
<tbody>
<tr><td>Композитная пломба</td><td>Оставшиеся стенки прочные, утрата вещества ограниченная, нагрузка невысокая</td><td>Вариант с наименьшей утратой тканей; при больших дефектах может быть недостаточным</td></tr>
<tr><td>Онлей / частичная перекрывающая реставрация</td><td>Одна или две стенки ослаблены, необходимо защитить бугры</td><td>Обеспечивает перекрытие без такого обтачивания тканей, как при коронке</td></tr>
<tr><td>Коронка</td><td>Большинство стенок утрачено, есть признаки трещины, нагрузка высокая</td><td>Обтачивается больше тканей; это необратимо</td></tr>
<tr><td>Штифт (опора внутри канала)</td><td>Если не осталось тканей, удерживающих реставрацию</td><td>Не укрепляет зуб; служит только для фиксации, а излишнее применение может повышать риск перелома корня</td></tr>
</tbody>
</table>
<p>Когда речь заходит о коронке, выбор материала — отдельная тема; она рассматривается на странице <a href="/ru/zirkonyum-dis-kaplama/">Циркониевые коронки</a>.</p>
<h2>Другие факторы, влияющие на решение</h2>
<ul>
<li><strong>Признаки трещины.</strong> При подозрении на трещину в зубе к перекрывающей реставрации переходят раньше.</li>
<li><strong>Сжимание и скрежетание.</strong> У людей, сжимающих зубы по ночам, нагрузка возрастает существенно; ночная каппа тоже может быть частью плана.</li>
<li><strong>Роль зуба в общем плане.</strong> Зуб, который станет опорой моста или будет поддерживать частичный протез, восстанавливают более защищённым способом.</li>
<li><strong>Опора дёсен и кости.</strong> При ослабленных опорных тканях план реставрации меняется.</li>
<li><strong>Характер смыкания.</strong> То, как устроен контакт с зубом-антагонистом, определяет распределение нагрузки.</li>
</ul>
<h2>Сроки</h2>
<p>После завершения лечения корневых каналов зуб закрывают временной пломбой до окончательной реставрации. Если это ожидание затягивается дольше необходимого, возникают два риска: подтекание по краю временной пломбы и перелом ослабленного зуба при жевании. Поэтому важно не откладывать окончательную реставрацию.</p>
<p>У некоторых зубов может быть предпочтительным короткое ожидание для наблюдения за заживлением. В таком случае вам чётко сообщат, почему выжидают и когда продолжат. Процесс в целом описан на странице <a href="/ru/tedavi-plani-ve-surec/">План лечения и его ход</a>.</p>
<h2>На что обращать внимание потом?</h2>
<p>Зуб после лечения корневых каналов может поражаться кариесом; поскольку у него нет пульпы, болевого предупреждения может не быть, и проблема развивается незаметно. Поэтому важны регулярные осмотры и очищение межзубных промежутков. Такие привычки, как раскалывание зубами твёрдой скорлупы или разгрызание льда, повышают риск перелома.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Обязательно ли темнеет зуб после лечения корневых каналов?</strong><br>Нет. Изменение цвета наблюдается не у каждого зуба; оно может быть связано с травмой в анамнезе и с остатками внутри канала. Если оно появилось, рассматриваются внутреннее отбеливание или реставрационные варианты.</p>
<p><strong>Правильно ли предлагать коронку, когда достаточно пломбы?</strong><br>Рекомендация должна разъясняться вместе с её обоснованием. Вы вправе спросить: «В каком состоянии мои оставшиеся стенки, есть ли вариант с меньшим обтачиванием тканей?»</p>
<p><strong>Укрепляет ли штифт зуб?</strong><br>Нет. Штифт используется только для удержания реставрации сверху; он не делает зуб прочнее и при ненужном применении может навредить.</p>
<p><strong>Если поставить коронку, зуб больше не создаст проблем?</strong><br>Коронка защищает зуб от перелома, но по её краю может развиться кариес, а опорные ткани могут заболеть. Потребность в уходе и осмотрах сохраняется.</p>
<p><strong>Лечение каналов закончено, но лёгкая чувствительность осталась — это нормально?</strong><br>В первые дни возможна чувствительность при жевании. При нарастающей боли, отёке или температуре следует без промедления обратиться в клинику.</p>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт тип реставрации после лечения корневых каналов выбирается с совместной оценкой сохранившихся здоровых тканей, группы зуба, риска трещины и жевательной нагрузки.</p>
<p><a href="/ru/kanal-tedavisi/">Лечение корневых каналов</a> &middot; <a href="/ru/agiz-dis-sagligi/">Здоровье полости рта и зубов</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'После лечения корневых каналов пломба или коронка? Решение определяют сохранившиеся здоровые ткани, группа зуба и жевательная нагрузка. Варианты и сроки.',
'RU' FROM blogs WHERE link = 'kanal-tedavisi-sonrasi-kaplama-her-zaman-gerekir-mi';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'Как справиться с чувствительностью после отбеливания зубов?',
'<p>Временная чувствительность к горячему и холодному после отбеливания — самый частый эффект этой процедуры. У большинства людей она быстро проходит и не требует прекращения лечения. Важно знать, почему возникает чувствительность, и планировать процедуру с учётом этого заранее.</p>
<h2>Почему возникает чувствительность?</h2>
<p>Отбеливающий состав проникает в эмаль и дентин и изменяет окрашенные молекулы. При этом стимулируется движение жидкости внутри дентина, и нервная ткань зуба воспринимает это как кратковременный раздражитель. Эффект обычно начинается во время процедуры или сразу после неё и уменьшается в течение часов или нескольких дней.</p>
<p>Эта картина не является признаком необратимого повреждения зуба. Однако длительность и выраженность различаются от человека к человеку; у части людей чувствительности не бывает вовсе.</p>
<h2>Что повышает риск</h2>
<ul>
<li>Обнажённая поверхность корня и рецессия десны</li>
<li>Стираемость эмали, трещины или клиновидные дефекты</li>
<li>Нелеченый кариес или негерметичная пломба</li>
<li>Активное воспаление десны</li>
<li>Ранее существовавшая чувствительность</li>
<li>Применение геля в большем количестве или дольше, чем рекомендовано</li>
<li>Выход геля на десну из-за плохо прилегающей каппы</li>
</ul>
<p>Поэтому перед отбеливанием проводится осмотр; при наличии кариеса, негерметичных реставраций и проблем дёсен сначала устраняются они. Вся оценка показаний изложена на странице <a href="/ru/dis-beyazlatma/">Отбеливание зубов</a>.</p>
<h2>Меры, которые можно принять до процедуры</h2>
<table>
<thead><tr><th>Мера</th><th>Цель</th></tr></thead>
<tbody>
<tr><td>Осмотр и подготовительное лечение</td><td>Сначала устранить кариес, негерметичные пломбы и воспаление десны</td></tr>
<tr><td>Выяснение истории чувствительности</td><td>Подобрать дозу, длительность и интервал сеансов индивидуально</td></tr>
<tr><td>Изготовление подходящей каппы</td><td>Предотвратить выход геля на десну</td></tr>
<tr><td>Рекомендованные врачом вспомогательные средства</td><td>Уменьшить раздражение дентинных канальцев</td></tr>
<tr><td>Реалистичный график</td><td>Избежать увеличения дозы ради быстрого результата</td></tr>
</tbody>
</table>
<h2>Что делать, если чувствительность началась?</h2>
<ol>
<li><strong>Сделайте перерыв.</strong> Одного или нескольких дней перерыва чаще всего достаточно; общая длительность планируется заново.</li>
<li><strong>Не увеличивайте дозу самостоятельно.</strong> Больше геля или более долгое ношение усиливают чувствительность.</li>
<li><strong>Избегайте очень горячих и очень холодных напитков.</strong> В первые дни комфортнее тёплое.</li>
<li><strong>Пользуйтесь пастой и средствами, которые рекомендовал врач.</strong> Не добавляйте средства по собственному решению.</li>
<li><strong>Используйте мягкую щётку и бережную технику.</strong> Жёсткая чистка усиливает чувствительность на обнажённой поверхности корня.</li>
<li><strong>Ограничьте кислые продукты.</strong> В этот период поверхность эмали более уязвима.</li>
</ol>
<h2>Когда звонить в клинику?</h2>
<p>Если чувствительность не уменьшается за несколько дней, продолжает нарастать или превращается в боль, возникающую самопроизвольно и по ночам, требуется оценка. К ожидаемой картине не относятся также незаживающий белый или покрасневший участок на десне, резкая боль, сосредоточенная в одном зубе, и боль при жевании. В таких случаях может быть скрытый кариес, трещина или проблема пульпы.</p>
<h2>Результат и стойкость цвета</h2>
<p>В первые дни рекомендуется ограничить тёмные напитки и продукты. Со временем частичный возврат оттенка является обычным; необходимость коррекции определяется на контрольном осмотре. Помните, что отбеливание действует только на собственные ткани зуба и цвет имеющихся пломб и коронок не меняется — эта тема рассматривается и в <a href="/ru/blog/hollywood-smile-nedir--mukemmel-guluse-giden-yol">статье об эстетическом планировании</a>.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Сколько дней держится чувствительность?</strong><br>У большинства людей от нескольких часов до нескольких дней. При её затягивании или усилении требуется осмотр.</p>
<p><strong>Нужно ли прекращать отбеливание, если появилась чувствительность?</strong><br>Обычно нет. Можно продолжить, сделав перерыв и заново подобрав дозу и длительность; решение принимается на контрольном осмотре.</p>
<p><strong>Можно ли принять обезболивающее?</strong><br>Приём препаратов определяется после консультации с вашим врачом. Сохраняющаяся боль — не столько состояние, которое нужно подавлять лекарством, сколько признак, который следует оценить.</p>
<p><strong>У меня есть чувствительность — значит, отбеливание мне совсем нельзя?</strong><br>В большинстве случаев его можно рассмотреть. Сначала выясняется причина чувствительности; при обнажённой поверхности корня, трещинах или кариесе они устраняются, и протокол адаптируется соответствующим образом.</p>
<p><strong>Что вызывает меньшую чувствительность — домашнее или клиническое отбеливание?</strong><br>Единого правила нет. В обоих случаях определяющими являются доза, длительность и индивидуальная реакция; метод выбирается по данным осмотра.</p>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт протокол отбеливания определяется после совместной оценки истории чувствительности, здоровья дёсен и состояния обнажённых поверхностей корня.</p>
<p><a href="/ru/dis-beyazlatma/">Отбеливание зубов</a> &middot; <a href="/ru/estetik/">Эстетическая стоматология</a> &middot; <a href="/ru/agiz-dis-sagligi/">Здоровье полости рта и зубов</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'Почему после отбеливания возникает чувствительность к горячему и холодному, что повышает риск, как с ней справиться? Когда нужно звонить в клинику?',
'RU' FROM blogs WHERE link = 'dis-beyazlatma-sonrasi-hassasiyet-nasil-yonetilir';

